-- Keep Day 1 practical and beginner-friendly without certification-style wording.
update public.lesson_blocks b
set content = updates.content
from public.lessons l,
  (values
    (1, 'text', '{"markdown":"Тестирование нужно, чтобы команда заранее понимала, как ведёт себя продукт и где он может подвести пользователя. Это не только поиск ошибок: мы проверяем важные сценарии, задаём вопросы к требованиям и помогаем принимать решения на основе фактов."}'::jsonb),
    (5, 'definition', '{"term":"Тестирование ПО","text":"Простыми словами: мы проверяем продукт в разных ситуациях и собираем понятную информацию о его качестве. Точнее: это работа по анализу, проверке и оценке продукта и связанных материалов, чтобы находить проблемы и снижать риски."}'::jsonb),
    (9, 'text', '{"markdown":"Ожидаемый результат — то, что должно произойти по требованию, макету или согласованному правилу. Фактический результат — то, что произошло на самом деле. Сравнение этих двух вещей помогает заметить проблему, но тестирование не сводится только к такому сравнению."}'::jsonb),
    (13, 'text', '{"markdown":"Testing — это проверка продукта. QA — работа, которая помогает не допускать проблем: делать требования понятнее, обсуждать риски заранее и улучшать процесс. QC — контроль результата на соответствие ожиданиям. В вакансиях «QA-инженером» часто называют специалиста, который тестирует продукт и помогает команде с качеством."}'::jsonb),
    (17, 'definition', '{"term":"Ошибка, дефект и отказ","text":"Ошибка — неверное решение человека. Дефект — проблема, которая попала в требование, код, данные или настройку. Отказ — то, что уже видит пользователь: например, приложение показывает неверную сумму или не открывает экран."}'::jsonb),
    (21, 'text', '{"markdown":"Тестировщик смотрит не только на обычный путь. Он пробует оставить поле пустым, ввести слишком длинное значение, нажать кнопку дважды или потерять интернет. Так команда раньше узнаёт, где пользователь может столкнуться с проблемой."}'::jsonb)
  ) as updates(position, block_type, content)
where b.lesson_id = l.id
  and l.day_number = 1
  and b.position = updates.position
  and b.block_type = updates.block_type;
